namespace sv_167f364a4f854578b094ada1492dae84.Models;

public sealed class Recipe
{
    public required int Id { get; init; }
    public required string Title { get; init; }
    public required string Description { get; init; }
    public required int PrepTimeMinutes { get; init; }
}

using sv_167f364a4f854578b094ada1492dae84.Models;

namespace sv_167f364a4f854578b094ada1492dae84.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> RecipesByCuisine = new()
    {
        [1] = new List<Recipe>
        {
            new() { Id = 1, Title = "Margherita Pizza", Description = "Classic Italian pizza with tomato, mozzarella, and basil.", PrepTimeMinutes = 30 },
            new() { Id = 2, Title = "Spaghetti Carbonara", Description = "Creamy pasta with pancetta, egg yolk, and Pecorino Romano.", PrepTimeMinutes = 25 },
            new() { Id = 3, Title = "Tiramisu", Description = "Layered coffee-flavored dessert with mascarpone cream.", PrepTimeMinutes = 45 },
        },
        [2] = new List<Recipe>
        {
            new() { Id = 4, Title = "Chicken Tikka Masala", Description = "Tender chicken in a rich, spiced tomato-cream sauce.", PrepTimeMinutes = 50 },
            new() { Id = 5, Title = "Palak Paneer", Description = "Cottage cheese cubes in a creamy spinach gravy.", PrepTimeMinutes = 35 },
            new() { Id = 6, Title = "Biryani", Description = "Fragrant basmati rice layered with spiced meat and herbs.", PrepTimeMinutes = 60 },
        },
        [3] = new List<Recipe>
        {
            new() { Id = 7, Title = "Sushi Rolls", Description = "Vinegared rice with fresh fish and vegetables wrapped in nori.", PrepTimeMinutes = 40 },
            new() { Id = 8, Title = "Ramen", Description = "Rich pork-bone broth with noodles, chashu, and soft-boiled egg.", PrepTimeMinutes = 55 },
            new() { Id = 9, Title = "Tempura", Description = "Lightly battered and deep-fried shrimp and vegetables.", PrepTimeMinutes = 20 },
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (RecipesByCuisine.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_167f364a4f854578b094ada1492dae84.Models
@using sv_167f364a4f854578b094ada1492dae84.Services
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation
@implements IDisposable

<PageTitle>Recipes</PageTitle>

<h1>Recipes — Cuisine @CuisineId</h1>

<nav class="mb-3">
    <a href="/recipes/1" class="btn btn-outline-primary me-1">Italian</a>
    <a href="/recipes/2" class="btn btn-outline-primary me-1">Indian</a>
    <a href="/recipes/3" class="btn btn-outline-primary me-1">Japanese</a>
</nav>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger d-flex align-items-center justify-content-between" role="alert">
        <span>@_errorMessage</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}

@if (_recipes is null && _errorMessage is null)
{
    <div class="d-flex align-items-center gap-2 my-4">
        <div class="spinner-border spinner-border-sm" role="status"></div>
        <span>Loading recipes…</span>
    </div>
}
else if (_recipes is not null)
{
    @if (_isRefreshing)
    {
        <div class="d-flex align-items-center gap-2 mb-3 text-muted">
            <div class="spinner-border spinner-border-sm" role="status"></div>
            <small>Refreshing…</small>
        </div>
    }

    <div class="row row-cols-1 row-cols-md-3 g-3">
        @foreach (var recipe in DisplayedRecipes)
        {
            <div class="col">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                    </div>
                    <div class="card-footer text-muted">
                        Prep time: @recipe.PrepTimeMinutes min
                    </div>
                </div>
            </div>
        }
    </div>

    @if (!DisplayedRecipes.Any())
    {
        <p class="text-muted mt-3">No recipes found for this cuisine.</p>
    }
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isRefreshing;
    private string? _errorMessage;
    private int _loadedCuisineId;
    private CancellationTokenSource? _loadCts;
    private readonly CancellationTokenSource _disposeCts = new();

    private IEnumerable<Recipe> DisplayedRecipes
    {
        get
        {
            if (_recipes is null) return Enumerable.Empty<Recipe>();

            return Sort?.ToLowerInvariant() switch
            {
                "popular" => _recipes.OrderByDescending(r => r.Id),
                "newest" => _recipes.OrderBy(r => r.PrepTimeMinutes),
                _ => _recipes,
            };
        }
    }

    protected override Task OnParametersSetAsync()
    {
        if (CuisineId != _loadedCuisineId)
        {
            return LoadRecipesAsync();
        }

        // Sort changed — no reload needed, just re-render.
        return Task.CompletedTask;
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load for the previous cuisine.
        await CancelPendingLoadAsync();

        _loadedCuisineId = CuisineId;
        _errorMessage = null;
        _isRefreshing = _recipes is not null;

        var cts = CancellationTokenSource.CreateLinkedTokenSource(_disposeCts.Token);
        _loadCts = cts;

        if (!_isRefreshing)
        {
            // First load — show spinner placeholder via null _recipes.
            StateHasChanged();
        }

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);

            if (cts.Token.IsCancellationRequested) return;

            _recipes = result;
            _isRefreshing = false;
        }
        catch (OperationCanceledException)
        {
            // Load was superseded or the component is disposing — nothing to do.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
    }

    private Task RetryAsync() => LoadRecipesAsync();

    private async Task CancelPendingLoadAsync()
    {
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
            _loadCts = null;
        }
    }

    public void Dispose()
    {
        _disposeCts.Cancel();
        _disposeCts.Dispose();
        _loadCts?.Cancel();
        _loadCts?.Dispose();
    }
}

